package com.paymentplatform.notification_service.api;
import com.paymentplatform.notification_service.domain.NotificationService;import com.paymentplatform.notification_service.security.ServiceActor;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.*;import java.util.UUID;
@RestController public class NotificationController {
 private final NotificationService service;public NotificationController(NotificationService service){this.service=service;}
 @PostMapping("/internal/v1/notifications") ResponseEntity<?> create(@AuthenticationPrincipal Jwt jwt,@Valid @RequestBody NotificationService.Request request){var result=service.create(jwt.getClaimAsString("integrator_id"),ServiceActor.requireService(jwt),request);return ResponseEntity.status(201).cacheControl(CacheControl.noStore()).header("Idempotency-Replayed",Boolean.toString(result.replayed())).body(result.response());}
 @GetMapping("/v1/customers/{customerId}/notifications") ResponseEntity<?> list(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID customerId,@RequestParam(required=false) UUID after,@RequestParam(defaultValue="50") @Min(1) @Max(100) int limit){ServiceActor.requireService(jwt);return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(service.list(jwt.getClaimAsString("integrator_id"),customerId,after,limit));}
 @PostMapping("/v1/customers/{customerId}/notifications/{id}/acknowledgement") ResponseEntity<?> acknowledge(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID customerId,@PathVariable UUID id){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(service.acknowledge(jwt.getClaimAsString("integrator_id"),ServiceActor.requireService(jwt),customerId,id));}
}
